import {useEffect, useId, useState} from "react";
import {InputLabel, SelectLabel} from "./InputLabel";
import {get, post, put} from "../utils/request";

export const ModalCategory = ({token,modalId, item, reload, clear}) => {
    const labelId = useId();
    const [alterItem, setAlterItem] = useState({
        id: '',
        name: '',
    })

    async function handleCreate(event){
        event.preventDefault();
        const res = await post('item-type',token,{
            name:alterItem.name
        })
        clear();
        reload();
    }
    async function handleAlter(event){
        event.preventDefault();
        const res = await put('item-type/' + alterItem.id,token,{
            name:alterItem.name
        })
        clear();
        reload();
    }

    // atualizando o objeto local toda vez que o item da página é atualizado
    useEffect(() => {
        setAlterItem({
            id: item.id,
            name: item.name
        })
    }, [item]);

    return (
        <div className="modal fade" id={modalId} data-bs-backdrop="static" data-bs-keyboard="false" tabIndex="-1"
             aria-labelledby={labelId} aria-hidden="true">
            <div className="modal-dialog modal-dialog-centered">
                <div className="modal-content">
                    <form onSubmit={item.id? handleAlter : handleCreate}>
                        <div className="modal-header">
                            <h2 className="modal-title fs-5" id={labelId}>Create category</h2>
                            <button type="button" className="btn-close" data-bs-dismiss="modal"
                                    aria-label="Close"></button>
                        </div>
                        <div className="modal-body">
                            <InputLabel
                                value={alterItem.name}
                                setValue={(event)=>{
                                    setAlterItem({
                                        ...alterItem,
                                        name: event.target.value
                                    })
                                }}
                            >Name</InputLabel>
                        </div>
                        <div className="modal-footer">
                            <button
                                className="btn btn-primary"
                                data-bs-dismiss="modal"
                            >Salve</button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    )
}

export const ModalItem = ({token,modalId, item, reload, clear}) => {
    const labelId = useId();
    const [alterItem, setAlterItem] = useState({
        id:'',
        item_name: '',
        type_id: ''
    })
    const [categoryList, setCategoryList] = useState([])
    async function handleCreate(event){
        event.preventDefault();
        console.log({
            item_name: alterItem.item_name,
            type_id: alterItem.type_id
        })

        const res = await post('stock-item',token,{
            item_name: alterItem.item_name,
            type_id: alterItem.type_id
        })
        const data = await res.json();
        console.log(data);
        clear();
        reload();
    }
    async function handleAlter(event){
        event.preventDefault();
        const res = await put('stock-item/' + alterItem.id,token,{
            item_name: alterItem.item_name,
            type_id: alterItem.type_id
        })
        clear();
        reload();
    }

    // carregando as categorias para o select
    async function loadCategories() {
        const res = await get('item-type', token);
        const data = await res.json();
        setCategoryList(data);
    }

    // atualizando o objeto local toda vez que o item da página é atualizado
    useEffect(() => {
        setAlterItem({
            id: item.id,
            item_name: item.item_name,
            type_id: item.type_id
        });
    }, [item]);

    useEffect(()=>{
        loadCategories()
    },[])

    return (
        <div className="modal fade" id={modalId} data-bs-backdrop="static" data-bs-keyboard="false" tabIndex="-1"
             aria-labelledby={labelId} aria-hidden="true">
            <div className="modal-dialog modal-dialog-centered">
                <div className="modal-content">
                    <form onSubmit={item.id? handleAlter : handleCreate}>
                        <div className="modal-header">
                            <h2 className="modal-title fs-5" id={labelId}>Create category</h2>
                            <button type="button" className="btn-close" data-bs-dismiss="modal"
                                    aria-label="Close">
                            </button>
                        </div>
                        <div className="modal-body">
                            <InputLabel
                                value={alterItem.item_name}
                                setValue={(event)=>{
                                    setAlterItem({
                                        ...alterItem,
                                        item_name: event.target.value
                                    })
                                }}
                            >Name</InputLabel>
                            <SelectLabel
                                value={alterItem.type_id}
                                setValue={(event)=>{
                                    setAlterItem({
                                        ...alterItem,
                                        type_id: event.target.value
                                    })
                                }}
                                list={categoryList}
                            >Categorias</SelectLabel>
                        </div>
                        <div className="modal-footer">
                            <button
                                className="btn btn-primary"
                                data-bs-dismiss="modal"
                            >Salve</button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    )
}


