import {useId} from "react";

export const InputLabel = ({value, setValue, type = 'text', required=true, children}) => {

    // criando um id para automação da label e do input
    const inputId= useId()

    return (
        <div className="mb-3">
            <label
                htmlFor={inputId}
                className="form-label"
            >{children}</label>
            <input
                type={type}
                className="form-control"
                id={inputId}
                value={value}
                onChange={setValue}
                required={required}
            />
        </div>
    )
}

export const SelectLabel = ({list, value, setValue, required=true, children}) => {

    // criando um id para automação da label e do input
    const inputId= useId()

    return (
        <div className="mb-3">
            <label
                htmlFor={inputId}
                className="form-label"
            >{children}</label>
            <select
                className={'form-select'}
                required={required}
                value={value}
                onChange={setValue}
            >
                <option value="" hidden={true}>Selecione uma categoria</option>
                {list.map((item,index)=>{
                    return(
                        <option value={item.id}>{item.name}</option>
                    )
                })}
            </select>
        </div>
    )
}