import {useEffect, useId, useState} from "react";
import {get, remove} from "../utils/request";
import {ModalCategory, ModalItem} from "../components/Modal";

export const ItemStock = ({route, setRoute}) => {
    // obtendo o token do usuário
    const token = localStorage.getItem('token')
    // lista para gerenciar os tipos de categorias
    const [itemsList, setItemsList] = useState([])
    // state para gerenciamento de um item em manuseio
    const [item, setItem] = useState({
        id:'',
        item_name: '',
        type_id: ''
    })
    // id do modal
    const modalId = useId();

    // quando o componente iniciar carregar os itens
    async function loadItems() {
        const res = await get('stock-item', token);
        const data = await res.json();
        setItemsList(data);
    }
    // deletar o item com base no id
    async function deleteItem(item){
        const res = await remove('stock-item/' + item.id,token)
        await loadItems();
    }
    // função para limpar todas as propriedades do state
    function clearItem(){
        setItem({
            id:'',
            item_name: '',
            type_id: ''
        })
    }
    useEffect(() => {
        loadItems()
    }, []);

    return (<>
        <ModalItem
            token={token}
            item={item}
            modalId={modalId}
            reload={loadItems}
            clear={clearItem}
        />
        <div className="row">
            <div className="col">
                <h2 className={'display-5'}>Stock Items</h2>
            </div>
            <div className="col-3 my-auto">
                <button
                    className="btn btn-primary"
                    data-bs-toggle="modal"
                    data-bs-target={'#' + modalId}
                    onClick={()=>{
                        clearItem()
                    }}
                >
                    New Item
                </button>
            </div>
        </div>

        <table className="table">
            <thead>
            <tr>
                <th>Name</th>
                <th>Category</th>
                <th className={'w-25'}>Actions</th>
            </tr>
            </thead>
            <tbody>

            {itemsList.map((item, index) => {
                return (<tr key={item.id}>
                    <td>{item.item_name}</td>
                    <td>{item.type.name}</td>
                    <td className={'d-flex gap-3'}>
                        <button
                            className="btn btn-outline-primary"
                            data-bs-toggle="modal"
                            data-bs-target={'#' + modalId}
                            onClick={()=>{
                                setItem(item)
                            }}
                        >
                            Alter
                        </button>
                        <button
                            className="btn btn-outline-danger"
                            onClick={()=>deleteItem(item)}
                        >
                            Delete
                        </button>
                    </td>
                </tr>)
            })}
            </tbody>
        </table>
    </>)
}