import {ModalEvent} from "../components/Modal";
import {forwardRef, useEffect, useId, useState} from "react";
import {SelectLabel} from "../components/InputLabel";
import {renderToReadableStream} from "react-dom/server";

export const Events = () => {
    const token = localStorage.getItem('token')
    const modalId = useId();
    const now = new Date();

    const [days, setDays] = useState([])
    const [month, setMonth] = useState(now.getMonth())

    // lista dos meses disponíveis
    const listMonth = [
        {
            id:0,
            name:'January'
        },
        {
            id:1,
            name:'February'
        },
        {
            id:2,
            name:'March'
        },
        {
            id:3,
            name:'April'
        },
        {
            id:4,
            name:'May'
        },
        {
            id:5,
            name:'June'
        },
        {
            id:6,
            name:'July'
        },
        {
            id:7,
            name:'August'
        },
        {
            id:8,
            name:'September'
        },
        {
            id:9,
            name:'October'
        },
        {
            id:10,
            name:'October'
        },
        {
            id:11,
            name:'December'
        },
    ]

    // função para calcular os dias disponíveis
    function loadDays(){
        const firstDayMonth = new Date(now.getFullYear(), month, 1);
        const lastDayMonth = new Date(now.getFullYear(), parseInt(month) +  1, 0);

        const listDays = [];
        let weekDay = firstDayMonth.getDay();

        for (let i = weekDay; i >  0; i--) {
            listDays.push({
                date: new Date(firstDayMonth.getTime() - i * 24 * 60 * 60 * 1000),
                currentMonth:false
            })
        }
        for (let i = 1; i <=  lastDayMonth.getDate(); i++) {
            listDays.push({
                date: new Date(firstDayMonth.getFullYear(), month, i),
                currentMonth:true
            })
        }

        weekDay = lastDayMonth.getDay();
        for (let i = 1; i + weekDay <= 7; i++) {
            listDays.push({
                date: new Date(firstDayMonth.getTime() + i * 24 * 60 * 60 * 1000),
                currentMonth:false
            })
        }

        console.log(listDays)

        setDays(listDays);
    }



    // renderizando os dias
    function renderDays(){
        let currentLine = [];
        let body  = [];

        days.forEach((item,index)=>{
            currentLine.push(
                <td key={item.date.getTime()}
                    className={'text-end'}>
                    {item.date.getDate()}
                </td>
            )

            if((index+1) % 7 === 0){
                body.push(
                    <tr>
                        {currentLine}
                    </tr>
                )
                currentLine = []
            }
        })

        return body;
    }

    useEffect(() => {
        loadDays()
    }, [month]);

    return (
        <>
            <div className="row">
                <div className="col">
                    <h2 className={'display-5'}>Events</h2>
                </div>
                <div className="col-3 my-auto">
                    <button
                        className="btn btn-primary"
                        data-bs-toggle="modal"
                        data-bs-target={'#' + modalId}
                    >
                        New event
                    </button>
                    <SelectLabel
                        list={listMonth}
                        value={month}
                        setValue={(event)=>{
                            setMonth(event.target.value)
                        }}
                    />
                </div>
            </div>

            <table className="table">
                <thead>
                <tr className={'text-end'}>
                    <th>Sun</th>
                    <th>Mon</th>
                    <th>Tue</th>
                    <th>Weds</th>
                    <th>Thu</th>
                    <th>Fri</th>
                    <th>Sat</th>
                </tr>
                </thead>
                <tbody>
                {renderDays()}
                </tbody>
            </table>
        </>
    )
}