import {InputLabel} from "../components/InputLabel";
import {useState} from "react";
import {post} from "../utils/request";

export const Login = ({route, setRoute}) => {

    // gerenciamento do usuário
    const [user, setUser] = useState({
        email: '',
        password: '',
    })
    // gerenciamento de mensagem de erro
    const [error, setError] = useState('');
    // gerenciamento de carregamento para o usuário
    const [load, setLoad] = useState(false)


    // função para o login do usuário
    async function handleSubmit(event) {
        event.preventDefault();
        setLoad(true)
        const res = await post('login', null, {
            email: user.email,
            password: user.password
        })
        if (res.ok) {
            const data = await res.json();
            localStorage.setItem('token',data.token)
            window.history.pushState(null, '', './events');
            setRoute('./events')
            return null;
        }
        setError('Email ou senha incorretos tente novamente')
        setLoad(false)
    }

    return (
        <>
            <h2 className="display-5">Login</h2>
            <form onSubmit={handleSubmit} className={'my-5 w-50'}>
                <InputLabel
                    type={'email'}
                    value={user.email}
                    setValue={(ev) => {
                        setUser({
                            ...user,
                            email: ev.target.value
                        })
                    }}
                >Email</InputLabel>
                <InputLabel
                    type={'password'}
                    value={user.password}
                    setValue={(ev) => {
                        setUser({
                            ...user,
                            password: ev.target.value
                        })
                    }}
                >Password</InputLabel>
                {
                    load &&
                    <div className="spinner-border" role="status">
                        <span className="visually-hidden">Loading...</span>
                    </div>
                }
                <p className={'text-danger'}>
                    {error}
                </p>
                <button type="submit" className="btn btn-primary">Submit</button>
            </form>
        </>
    )
}