import {InputLabel} from "../components/InputLabel";
import {useEffect, useId, useState} from "react";
import {get, remove} from "../utils/request";
import {ModalCategory} from "../components/Modal";
import modal from "bootstrap/js/src/modal";

export const Categories = ({route, setRoute}) => {
    // obtendo o token do usuário
    const token = localStorage.getItem('token')
    // lista para gerenciar os tipos de categorias
    const [categoryList, setCategoryList] = useState([])
    // state para gerenciamento de um item em manuseio
    const [item, setItem] = useState({
        id:'',
        name: ''
    })
    // id do modal
    const modalId = useId();

    // carregar as categorias
    async function loadCategories() {
        const res = await get('item-type', token);
        const data = await res.json();
        setCategoryList(data);
    }

    // deletando a categoria com base no id
    async function deleteItem(item){
        const res = await remove('item-type/' + item.id,token)
        loadCategories();
    }

    // função para limpar todas as propriedades do state
    function clearItem(){
        setItem({
            id:'',
            name:''
        })
    }

    useEffect(() => {
        loadCategories()
    }, []);

    return (<>
        <ModalCategory
            token={token}
            item={item}
            setItem={setItem}
            modalId={modalId}
            reload={loadCategories}
            clear={clearItem}
        />
        <div className="row">
            <div className="col">
                <h2 className={'display-5'}>Categories</h2>
            </div>
            <div className="col-3 my-auto">
                <button
                    className="btn btn-primary"
                    data-bs-toggle="modal"
                    data-bs-target={'#' + modalId}
                    onClick={()=>{
                        clearItem()
                    }}
                >
                    New Category
                </button>
            </div>
        </div>

        <table className="table">
            <thead>
            <tr>
                <th>Name</th>
                <th className={'w-25'}>Actions</th>
            </tr>
            </thead>
            <tbody>

            {categoryList.map((item, index) => {
                return (<tr key={item.id}>
                    <td>{item.name}</td>
                    <td className={'d-flex gap-3'}>
                        <button
                            className="btn btn-outline-primary"
                            data-bs-toggle="modal"
                            data-bs-target={'#' + modalId}
                            onClick={()=>{
                                setItem(item)
                            }}
                        >
                            Alter
                        </button>
                        <button
                            className="btn btn-outline-danger"
                            onClick={()=>deleteItem(item)}
                        >
                            Delete
                        </button>
                    </td>
                </tr>)
            })}
            </tbody>
        </table>
    </>)
}