import {InputLabel} from "../components/InputLabel";
import {useState} from "react";
import {post} from "../utils/request";

export const Signin = ({route, setRoute}) => {

    // gerenciamento das informações do novo usuário
    const [user, setUser] = useState({
        name:'',
        email:'',
        password:'',
        confirm_password:''
    })
    // gerenciamento de mensagem de erro
    const [error, setError] = useState('');
    // gerenciamento de carregamento para o usuário
    const [load, setLoad] = useState(false)

    // função para o registro do usuário
    async function handleSubmit(event){
        event.preventDefault();
        setLoad(true)
        const res = await post('register', null, {
            name: user.name,
            email: user.email,
            password: user.password,
            confirm_password: user.confirm_password,
        })
        if (res.ok) {
            window.history.pushState(null, '', '/');
            setRoute('/')
            return null;
        }
        const data = await res.json();
        setError(data.message)
        setLoad(false)
    }

    return(
        <>
            <h2 className={'display-5'}>Sign-in</h2>
            <form onSubmit={handleSubmit} className={'my-5 w-50'}>
                <InputLabel
                    value={user.name}
                    setValue={(ev) => {
                        setUser({
                            ...user,
                            name: ev.target.value
                        })
                    }}
                >Username</InputLabel>
                <InputLabel
                    type={'email'}
                    value={user.email}
                    setValue={(ev) => {
                        setUser({
                            ...user,
                            email: ev.target.value
                        })
                    }}
                >Email</InputLabel>
                <InputLabel
                    type={'password'}
                    value={user.password}
                    setValue={(ev) => {
                        setUser({
                            ...user,
                            password: ev.target.value
                        })
                    }}
                >Password</InputLabel>
                <InputLabel
                    type={'password'}
                    value={user.confirm_password}
                    setValue={(ev) => {
                        setUser({
                            ...user,
                            confirm_password: ev.target.value
                        })
                    }}
                >Confirm the password</InputLabel>
                {
                    load &&
                    <div className="spinner-border" role="status">
                        <span className="visually-hidden">Loading...</span>
                    </div>
                }
                <p className={'text-danger'}>
                    {error}
                </p>
                <button type="submit" className="btn btn-primary">Submit</button>
            </form>
        </>
    )
}