import {createContext, useEffect, useState} from "react";
import {Login} from "./pages/Login";
import {Link} from "./components/Link";
import {Signin} from "./pages/Signin";
import {Events} from "./pages/Events";
import {Categories} from "./pages/Categories";
import {ItemStock} from "./pages/ItemStock";

export const ContextNavigation = createContext(null)

function App() {

    // usestate para gerenciamento da rota do usuário
    const [route, setRoute] = useState('')

    // se o token está disponível antes de mais nada
    const token = localStorage.getItem('token')

    // uma listagem das rotas através do nome das propriedades
    const routes = {
        '/': <Login route={route} setRoute={setRoute}/>,
        '/sign-in': <Signin route={route} setRoute={setRoute}/>,
        '/events': <Events route={route} setRoute={setRoute}/>,
        '/categories': <Categories route={route} setRoute={setRoute}/>,
        '/items-stock': <ItemStock route={route} setRoute={setRoute}/>,
    }

    // para obter a parte que nos interessa da url
    function getRightUrl() {
        return '/' + window.location.pathname.slice(14)
        // return window.location.pathname;
    }

    // para deslogar o usuário do sistema
    function handleLogout(event){
        event.preventDefault();
        localStorage.removeItem('token')
        window.history.pushState(null, '','./');
        setRoute('./')
    }

    useEffect(() => {
        // adicionando o efeito de atualizar a url se o usuário pressionar o botão de voltar
        window.addEventListener('popstate',()=>{
            setRoute(getRightUrl())
        })
    }, []);

    // buscando o componente que nos interessa
    let component = routes[getRightUrl()]

    // validando o componente, se ele for igual a rota de login no entanto houver o token vai para eventos
    if(token && route === ''){
        component = routes['/events']
    }

    // se o o token não existe e for diferente de login e diferente de inscrever-se vai para login
    if(!token && (route !== '/' && '/sign-in' !== route)){
        component = routes['/']
    }

    return (
        <ContextNavigation.Provider value={{route, setRoute}}>
            <div className="d-flex h-100">
                <header className="vh-100 bg-dark w-25 pt-5 text-white">
                    <div className="container text-dark mb-3">
                        <h1 className={'display-5 text-white fw-bold'}>Ponto de luz</h1>
                    </div>
                    <div className="container bg-dark border-0">
                        <ul className="navbar-nav justify-content-end flex-grow-1 pe-3">
                            {
                                !!token ?
                                    <>
                                        <li className="nav-item dropdown">
                                            <a className="nav-link dropdown-toggle" href="#" role="button"
                                               data-bs-toggle="dropdown"
                                               aria-expanded="false">
                                                Events
                                            </a>
                                            <ul className="dropdown-menu  bg-secondary">
                                                <li>
                                                    <Link to={'./events'}>All Events</Link>
                                                </li>
                                            </ul>
                                        </li>
                                        <li className="nav-item dropdown">
                                            <a className="nav-link dropdown-toggle" href="#" role="button"
                                               data-bs-toggle="dropdown"
                                               aria-expanded="false">
                                                Stock
                                            </a>
                                            <ul className="dropdown-menu  bg-secondary">
                                                <li>
                                                    <Link to={'./events'}>Current Stock</Link>
                                                </li>
                                                <li>
                                                    <Link to={'./events'}>Stock Movements</Link>
                                                </li>
                                                <li>
                                                    <Link to={'./items-stock'}>Stock items</Link>
                                                </li>
                                                <li>
                                                    <Link to={'./categories'}>Categories</Link>
                                                </li>
                                            </ul>
                                        </li>
                                        <li className={'nav-item'}>
                                            <a
                                                href='#'
                                                className={'text-danger'}
                                                onClick={handleLogout}
                                            >Logout</a>
                                        </li>
                                    </>
                                    :
                                    <li className="nav-item dropdown">
                                        <a className="nav-link dropdown-toggle" href="#" role="button"
                                           data-bs-toggle="dropdown"
                                           aria-expanded="false">
                                            Profile
                                        </a>
                                        <ul className="dropdown-menu bg-secondary">
                                            <li>
                                                <Link to={'./'}>Login</Link>
                                            </li>
                                            <li>
                                                <Link to={'./sign-in'}>Sign in</Link>
                                            </li>
                                        </ul>
                                    </li>
                            }

                        </ul>
                    </div>
                </header>
                <div className={'container mt-5'}>
                    <div className="container">
                        {component}
                    </div>
                </div>

            </div>
        </ContextNavigation.Provider>
    );
}

export default App;
